                items = list(v.items())
                print(k, ':', len(items), 'entries. First 3:', items[:3])
            else:
                print(k, ':', v if not isinstance(v, list) or len(v)<10 else f'list len={len(v)} first={v[:5]}')
    else:
        print('list len =', len(d), 'first 2:', d[:2])
